mapper.select:
SELECT *
FROM assessment_rule
WHERE 1 = 1

    AND rule_type = #{q.ruleType}


    AND rule_section = #{q.ruleSection}


    AND rule_name LIKE CONCAT('%', #{q.keyword}, '%')


    AND status = #{q.status}

ORDER BY rule_section, rule_code

mapper.update:
UPDATE assessment_rule
SET status = #{status}
WHERE id = #{id}
